163	function unesc(s){return s.replace(/&(lt|gt|amp|quot|apos|#x[0-9a-fA-F]+|#\d+);/g,function(m,e){if(e==='lt')return'<';if(e==='gt')return'>';if(e==='amp')return'&';if(e==='quot')return'"';if(e==='apos')return"'";if(e[1]==='x')return String.fromCodePoint(parseInt(e.slice(2),16));return String.fromCodePoint(parseInt(e.slice(1),10));});}
