169	async function readZip(u8,inflateRaw,wanted){var dv=new DataView(u8.buffer,u8.byteOffset,u8.byteLength);var eocd=-1;for(var i=u8.length-22;i>=Math.max(0,u8.length-70000);i--){if(dv.getUint32(i,true)===0x06054b50){eocd=i;break;}}if(eocd<0)throw new Error('檔案不是有效的 .xlsx');var n=dv.getUint16(eocd+10,true);var p=dv.getUint32(eocd+16,true);var out={};var dec=new TextDecoder('utf-8');for(var k=0;k<n;k++){if(dv.getUint32(p,true)!==0x02014b50)break;var method=dv.getUint16(p+10,true);var csize=dv.getUint32(p+20,true);var nlen=dv.getUint16(p+28,true),xlen=dv.getUint16(p+30,true),clen=dv.getUint16(p+32,true);var lho=dv.getUint32(p+42,true);var name=dec.decode(u8.subarray(p+46,p+46+nlen));p+=46+nlen+xlen+clen;if(wanted&&!wanted(name))continue;var lnl=dv.getUint16(lho+26,true),lxl=dv.getUint16(lho+28,true);var start=lho+30+lnl+lxl;var data=u8.subarray(start,start+csize);var raw;if(method===0)raw=data;else if(method===8)raw=await inflateRaw(data);else continue;out[name]=dec.decode(raw);}return out;}
170	async function parseWorkbook(u8,inflateRaw){var files=await readZip(u8,inflateRaw,function(n){return/^xl\/(workbook\.xml|_rels\/workbook\.xml\.rels|sharedStrings\.xml|worksheets\/sheet\d+\.xml)$/.test(n);});var wbx=files['xl/workbook.xml'];if(!wbx)throw new Error('找不到 workbook.xml');var rels={};(files['xl/_rels/workbook.xml.rels']||'').replace(/<Relationship\b([^>]*)\/?>/g,function(m,a){rels[attr(a,'Id')]=attr(a,'Target');});var ss=[];var sst=files['xl/sharedStrings.xml']||'';sst.replace(/<si>([\s\S]*?)<\/si>/g,function(m,inner){inner=inner.replace(/<rPh\b[\s\S]*?<\/rPh>/g,'');var t='';inner.replace(/<t(?:\s[^>]*)?>([\s\S]*?)<\/t>/g,function(m2,x){t+=unesc(x);});ss.push(t);});var sheets={},order=[];var sheetRe=/<sheet\b([^>]*)\/>/g;var m;while((m=sheetRe.exec(wbx))){var sname=attr(m[1],'name');var rid=attr(m[1],'r:id');var target=rels[rid]||'';target=target.replace(/^\/?xl\//,'').replace(/^\//,'');var xml=files['xl/'+target];order.push(sname);sheets[sname]=xml?parseSheet(xml,ss):{cells:{}};}return{sheets:sheets,order:order};}
