247	function migrateDb(raw) {
248	  if (!raw) return null;
249	  if (!raw.schemaVersion || raw.schemaVersion < 2) {
250	    raw.schemaVersion = 2;
251	    raw.auditLogs = raw.auditLogs || [];
252	    for (var i = 0; i < (raw.projects || []).length; i++) {
253	      var p = raw.projects[i];
254	      p.schemaVersion = 2;
255	      p.createdAt = p.uploadedAt || p.createdAt || raw.today || '';
256	      p.updatedAt = p.updatedAt || p.createdAt;
257	      if (!p.contacts) p.contacts = { plant: '', hq: '' };
258	      if (!p.reports) p.reports = {};
259	      if (!p.mode) p.mode = 'formula';
260	      if (!p.reportRows) p.reportRows = [];
261	    }
262	  }
263	  return raw;
264	}
