266	function loadDb() {
267	  try { var s = localStorage.getItem(KEY); if (s) return migrateDb(JSON.parse(s)); } catch(e) {}
268	  return null;
269	}
270	
271	var db = loadDb() || { schemaVersion: SCHEMA_VERSION, version: 1, projects: [], notices: [], auditLogs: [], today: new Date().toISOString().slice(0,10), seq: 1 };
