280	function save() {
281	  try {
282	    var data = JSON.stringify(db);
283	    var kb = Math.round(data.length * 2 / 1024);
284	    if (kb > STORAGE_MAX_KB) { toast('⚠ 儲存空間接近上限（' + kb + ' KB），請先匯出備份！'); return false; }
285	    localStorage.setItem(KEY, data);
286	    if (kb > STORAGE_WARN_KB) toast('注意：儲存空間已用 ' + kb + ' KB，建議匯出備份。');
287	    return true;
288	  } catch(e) {
289	    if (e.name === 'QuotaExceededError') toast('❌ 儲存空間已滿！請立即匯出備份並清理資料。');
290	    else toast('保存失敗：' + e.message);
291	    return false;
292	  }
293	}
