295	function summarizeAuditValue(v) {
296	  if (v == null) return null;
297	  if (typeof v === 'number') return v;
298	  if (typeof v === 'string') return v.slice(0, 120);
299	  if (typeof v === 'object') {
300	    if (v.irrAfter !== undefined) return { irrAfter: v.irrAfter };
301	    if (v.values) return { valueCount: Object.keys(v.values).length };
302	    return '[object]';
303	  }
304	  return String(v).slice(0, 120);
305	}
