307	function addAuditLog(action, projectId, year, before, after, details) {
308	  if (!db.auditLogs) db.auditLogs = [];
309	  db.auditLogs.push({ action: action, timestamp: db.today, projectId: projectId || null, year: year || null, before: summarizeAuditValue(before), after: summarizeAuditValue(after), details: details || '' });
310	  if (db.auditLogs.length > 500) db.auditLogs = db.auditLogs.slice(-500);
