313	function exportData() {
314	  var payload = { exportVersion: 1, schemaVersion: SCHEMA_VERSION, appVersion: APP_VERSION, exportedAt: new Date().toISOString(), data: JSON.parse(JSON.stringify(db)) };
315	  var blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
316	  var url = URL.createObjectURL(blob);
317	  var a = document.createElement('a');
318	  a.href = url; a.download = 'irr-tracker-backup-' + new Date().toISOString().slice(0,10) + '.json';
319	  a.click(); URL.revokeObjectURL(url);
320	  addAuditLog('export', null, null, null, null, 'Data exported'); save();
321	  toast('已匯出備份');
322	}
