394	function compute(p, liveForm) {
395	  var actuals = {}, params = {};
396	  for (var y in p.reports) {
397	    actuals[y] = Object.assign({}, p.reports[y].values);
398	    Object.assign(params, p.reports[y].params || {});
399	  }
400	  if (liveForm) actuals[liveForm.year] = Object.assign({}, actuals[liveForm.year] || {}, liveForm.values);
401	  if (!E.buildOverrides) return { irr: null, payback: null, rows: {}, fallbacks: [], error: 'IRR Engine 未載入，請重新整理頁面。' };
402	  try {
403	    var ov = E.buildOverrides(p.model, p.baseline, actuals, params, p.mode, p.reportRows);
404	    var calc = E.makeCalc(p.wb, ov);
405	    var snap = E.snapshot(calc, p.model);
406	    snap.fallbacks = calc.fallbacks || [];
407	    return snap;
408	  } catch(e) {
409	    return { irr: { err: '#ERROR!' }, payback: null, rows: {}, fallbacks: [], error: e.message };
410	  }
411	}
