413	function schedule(p) {
414	  var out = [];
415	  for (var n = 1; n <= p.model.horizon; n++) {
416	    var periodStart = addYears(p.startDate, n - 1);
417	    var periodEnd = addDays(addYears(p.startDate, n), -1);
418	    var due = addDays(periodEnd, p.graceDays);
419	    var rep = p.reports[n];
420	    var st = 'idle';
421	    if (rep) st = 'ok';
422	    else if (today() > due) st = 'late';
423	    else if (today() > periodEnd) st = 'due';
424	    out.push({ year: n, periodStart: periodStart, periodEnd: periodEnd, due: due, status: st, rep: rep });
425	  }
426	  return out;
427	}
