432	  var s = schedule(p);
433	  for (var i = 0; i < s.length; i++) if (s[i].status === 'late') return s[i];
434	  for (var i = 0; i < s.length; i++) if (s[i].status === 'due') return s[i];
435	  for (var i = 0; i < s.length; i++) if (s[i].status === 'idle') return s[i];
